#include "stdlib/blas/ext/base/dcross.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Computes the cross product of two double-precision floating-point input strided arrays and assigns the results to an output strided array.
*
* @param X        first input array
* @param strideX  stride length for X
* @param Y        second input array
* @param strideY  stride length for Y
* @param Z        output array
* @param strideZ  stride length for Z
*/
void API_SUFFIX(stdlib_strided_dcross)( const double *X, const CBLAS_INT strideX, const double *Y, const CBLAS_INT strideY, double *Z, const CBLAS_INT strideZ ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( 3, strideX );
	CBLAS_INT oy = stdlib_strided_stride2offset( 3, strideY );
	CBLAS_INT oz = stdlib_strided_stride2offset( 3, strideZ );
	API_SUFFIX(stdlib_strided_dcross_ndarray)( X, strideX, ox, Y, strideY, oy, Z, strideZ, oz );
}

/**
* Computes the cross product of two double-precision floating-point input strided arrays and assigns the results to an output strided array using alternative indexing semantics.
*
* @param X        first input array
* @param strideX  stride length for X
* @param offsetX  starting index for X
* @param Y        second input array
* @param strideY  stride length for Y
* @param offsetY  starting index for Y
* @param Z        output array
* @param strideZ  stride length for Z
* @param offsetZ  starting index for Z
*/
void API_SUFFIX(stdlib_strided_dcross_ndarray)( const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY, double *Z, const CBLAS_INT strideZ, const CBLAS_INT offsetZ ) {
	double x0;
	double x1;
	double x2;
	double y0;
	double y1;
	double y2;

	// Cache array elements...
	x0 = X[ offsetX ];
	x1 = X[ offsetX+strideX ];
	x2 = X[ offsetX+(2*strideX) ];
	y0 = Y[ offsetY ];
	y1 = Y[ offsetY+strideY ];
	y2 = Y[ offsetY+(2*strideY) ];

	// Resolve cross product...
	Z[ offsetZ ] = (x1*y2) - (x2*y1);
	Z[ offsetZ+strideZ ] = (x2*y0) - (x0*y2);
	Z[ offsetZ+(2*strideZ) ] = (x0*y1) - (x1*y0);
}
